internal val LOCALE_DISPLAY_NAMES_LO: String =
    "root\u001F4gອະຟາ\u001Eແອບຄາຊຽນ\u001Eແອັກຊີເນັສ\u001Eອາໂຄລີ\u001Eອາແດງມີ\u001Eເອດີຮິ\u001Eອາເວັສແຕນ\u001Eອາຟຣິການ\u001Eແອຟີຮີລີ\u001Eອາເຮັມ\u001Eໄອນູ\u001Eອາການ\u001Eອັກກາດຽມ\u001Eອາເລີດ\u001Eອານໄຕໃຕ້\u001Eອຳຮາຣິກ\u001Eອາຣາໂກເນັດ\u001Eອັງກິດໂບຮານ\u001Eໂອໂບໂລ\u001Eແອນຈີກາ\u001Eອາຣັບ\u001Eອາຣາບິກມາດຕະຖານສະໄໝໃໝ່\u001Eອາລາມິກ\u001Eມາພຸດຊີ\u001Eອາຣາປາໂຮ\u001Eນາຈດີ ອາຣາບິກ\u001Eອາຣາແວກ\u001Eອັສຊາມີສ\u001Eອາຊູ\u001Eອັສຕູຮຽນ\u001Eອາຕິກາແມກ\u001Eອາວາຣິກ\u001Eອາວາຮິ\u001Eອາຍມາລາ\u001Eອາເຊີໄບຈານິ\u001Eອາ​ເຊີ​ຣີ\u001Eບາຣກີ\u001Eບາລູຊີ\u001Eບາລີເນັດ\u001Eບາຊາ\u001Eບາມຸນ\u001Eໂຄມາລາ\u001Eເບລາຣັສຊຽນ\u001Eບີເຈ\u001Eເບັມບາ\u001Eບີນາ\u001Eບາຟັດ\u001Eບັງກາຣຽນ\u001Eຮາຢານວີ\u001Eບາໂລຈີ ພາກຕາເວັນຕົກ\u001Eໂບພູຣິ\u001Eບິສລະມາ\u001Eບີຄອນ\u001Eບີນີ\u001Eກົມ\u001Eຊິກຊິກາ\u001Eອານີ\u001Eບາມບາຣາ\u001Eເບັງກາລີ\u001Eທິເບທັນ\u001Eເບຣຕັນ\u001Eບຣາ\u001Eໂບດູ\u001Eບອສນຽນ\u001Eອາຄຸດ\u001Eບູຣຽດ\u001Eບູຈີເນັດ\u001Eບູລູ\u001Eບລິນ\u001Eເມດູມບາ\u001Eຄາຕາລານ\u001Eແຄດໂດ\u001Eຄາຣິບ\u001Eຄາຢູກາ\u001Eອາດແຊມ\u001Eຊາກມາ\u001Eຊີເຄນ\u001Eຊີບູໂນ\u001Eຊີກາ\u001Eຊາມໍໂຣ\u001Eຊິບຊາ\u001Eຊາກາໄຕ\u001Eຊູເກດ\u001Eມາຣິ\u001Eຊີນຸກຈາກອນ\u001Eຊອກຕິວ\u001Eຊີພິວຢານ\u001Eຊີໂຣກີ\u001Eຊີເຢນນີ\u001Eໂຊຣານິ ເຄີດິຊ\u001Eຊິວໂຄຕິນ\u001Eຄໍຊິກາ\u001Eຄອບຕິກ\u001Eຄີ\u001Eມິຊິຟ\u001Eຄຣີເມນເຕີຄິຊ\u001Eຄຣີຕາເວັນອອກສ່ຽງໃຕ້\u001Eເພລນຄຣີ\u001Eຄຣີຕາເວັນອອກສ່ຽງເໜືອ\u001Eມູສຄຣີ\u001Eຄາໂຣລິນາ ອາກອນຄວຽນ\u001Eເຊເຊວາ ໂຄຣດ ຝຣັ່ງ\u001Eເຊກ\u001Eກາຊູບຽນ\u001Eຊວາມປີຄຣີ\u001Eໂບດສລາວິກ\u001Eຊູວາຊ\u001Eເວວ\u001Eແດນິຊ\u001Eດາໂກຕາ\u001Eດາກວາ\u001Eໄຕຕາ\u001Eເຢຍລະມັນ\u001Eເຢຍລະມັນ (ໂອສຕຣິດ)\u001Eສະວິສ ໄຮ ເຈີແມນ\u001Eເດລາວາ\u001Eຊີເລັບ\u001Eໂດກຣິບ\u001Eດິນກາ\u001Eຊາມາ\u001Eດອກຣີ\u001Eຊໍບຽນຕໍ່ກວ່າ\u001Eດົວລາ\u001Eດັກກາງ\u001Eດີວີຮີ\u001Eໂຈລາ-ຟອນຢີ\u001Eດູລາ\u001Eດີຊອງຄາ\u001Eດາຊາກາ\u001Eເອັມບູ\u001Eອິວາ\u001Eອີຟິກ\u001Eອີຢິບບູຮານ\u001Eອີກາຈັກ\u001Eກຣີກ\u001Eອີລາໄມ\u001Eອັງກິດ\u001Eອັງກິດ (ບຣິດທິຊ)\u001Eອັງກິດ (ສະຫະລາດຊະອານາຈັກ)\u001Eອັງກິດ (ອາເມລິກັນ)\u001Eອັງກິດ (ສະຫະລັດອາເມລິກາ)\u001Eອັງກິດກາງ\u001Eເອສປາຍ\u001Eສະແປນນິຊ\u001Eລາຕິນ ອາເມຣິກັນ ສະແປນນິຊ\u001Eສະເປັນ ຢຸໂຣບ\u001Eເມັກຊິກັນ ສະແປນນິຊ\u001Eເອສໂຕນຽນ\u001Eບັສກີ\u001Eອີວອນດູ\u001Eເປີຊຽນ\u001Eດາຣີ\u001Eແຟງ\u001Eແຟນຕີ\u001Eຟູລາ\u001Eຟິນນິຊ\u001Eຟີລິປີໂນ\u001Eຟິຈຽນ\u001Eຟາໂຣສ\u001Eຟອນ\u001Eຝຣັ່ງ\u001Eຝຣັ່ງ (ສວິສ)\u001Eຝຣັ່ງເຄຈຸນ\u001Eຟຮັ່ງເສດກາງ\u001Eຟຮັ່ງເສດໂບຮານ\u001Eຟຣີຊຽນເໜືອ\u001Eຟຣີຊຽນຕາເວັນອອກ\u001Eຟຣີລຽນ\u001Eຟຣິຊຽນ ຕາເວັນຕົກ\u001Eໄອຣິສ\u001Eກາ\u001Eກາກາອຸຊ\u001Eກາໂຢ\u001Eບາຍາ\u001Eສະກັອດເກລິກ\u001Eກີ\u001Eກິນເບີເທັດ\u001Eກາລິຊຽນ\u001Eເຢຍລະມັນສູງກາງ\u001Eກົວຣານີ\u001Eເຢຍລະມັນສູງໂບຮານ\u001Eກອນດີ\u001Eໂກຣອນຕາໂຣ\u001Eກອດຮິກ\u001Eກຣີໂບ\u001Eແອນຊຽນກຣີກ\u001Eສະວິສ ເຈີແມນ\u001Eກູຈາຣາຕິ\u001Eກູຊິ\u001Eແມງຊ໌\u001Eວິດອິນ\u001Eເຮົາຊາ\u001Eໄຮດາ\u001Eຮາໄວອຽນ\u001Eໄຮດາໃຕ້\u001Eຮີບຣິວ\u001Eຮິນດິ\u001Eຮິຣິໄກນອນ\u001Eຮິດໄຕ\u001Eມອງ\u001Eຮິຣິໂມຕູ\u001Eໂຄຣເອທຽນ\u001Eຊໍບຽນ ທາງຕອນເໜືອ\u001Eໄຮຕຽນ\u001Eຮັງກາຣຽນ\u001Eຮູປາ\u001Eຮາລໂກເມລຽມ\u001Eອາເມນຽນ\u001Eເຮິຮິໂຣ\u001Eອິນເຕີລິງລົວ\u001Eໄອບານ\u001Eໄອໄບໄບໂອ\u001Eອິນໂດເນຊຽນ\u001Eອິນເຕີລິງກຣີ\u001Eອິກໂບ\u001Eເສສວນ ອີ\u001Eອິນນູປຽກ\u001Eອິນັກທິທັດຄານາດາຕາເວັນຕົກ\u001Eໄອໂລໂກ\u001Eອິນກັຊ\u001Eອີໂດ\u001Eໄອສແລນດິກ\u001Eອິຕາລຽນ\u001Eອິນນຸກຕິຕັດ\u001Eຍີ່ປຸ່ນ\u001Eໂລບບັນ\u001Eງອມບາ\u001Eມາແຊມ\u001Eຈູແດວ-ເພີຊຽນ\u001Eຈູແດວ-ອາລາບິກ\u001Eຈາແວນີສ\u001Eຈໍຈຽນ\u001Eກາຣາ-ການປາກ\u001Eກາໄບລ໌\u001Eກາຊິນ\u001Eຈຣູ\u001Eກາມບາ\u001Eກະວີ\u001Eກາບາດຽນ\u001Eຄາແນມບູ\u001Eຕີບ\u001Eມາຄອນເດ\u001Eຄາເວີເດຍນູ\u001Eໂຄໂລ\u001Eຄອງໂກ\u001Eເຄນກັງ\u001Eຄາສິ\u001Eໂຄຕັນ\u001Eຄອຍຣາ ຊິນີ\u001Eຄິຄູຢຸ\u001Eກວນຍາມາ\u001Eຄາຊັກ\u001Eຄາໂກ\u001Eກຣີນແລນລິດ\u001Eຄາເລັນຈິນ\u001Eຂະເໝນ\u001Eຄິມບັນດູ\u001Eຄັນນາດາ\u001Eເກົາຫລີ\u001Eໂຄມີ-ເພີມຢັກ\u001Eກອນການີ\u001Eຄູສໄລ\u001Eກາແປຣ\u001Eຄານຸລິ\u001Eກາຣາໄຊ-ບານກາ\u001Eກາເຣລຽນ\u001Eກູຣູກ\u001Eຄາສເມຍຣິ\u001Eຊຳບາລ້າ\u001Eບາເຟຍ\u001Eໂຄລອກນຽນ\u001Eເຄີດິສ\u001Eຄູມີກ\u001Eຄູເທໄນ\u001Eໂຄມິ\u001Eຄໍນິຊ\u001Eຄວາກຄວາກລາ\u001Eຄູວີ\u001Eເກຍກີສ\u001Eລາຕິນ\u001Eລາດີໂນ\u001Eແລນກິ\u001Eລານດາ\u001Eແລມບາ\u001Eລັກເຊມບວກກິຊ\u001Eລີຊຽນ\u001Eແກນດາ\u001Eລິມເບີກີຊ\u001Eລີກູຣຽນ\u001Eລິນລູເອັດ\u001Eລາໂກຕາ\u001Eລອມບາດ\u001Eລິງກາລາ\u001Eລາວ\u001Eແມັງໂກ້\u001Eລຸຍຊີອານນາ ຄຣີໂອນ\u001Eໂລຊິ\u001Eລູຣິ ທາງຕອນເໜືອ\u001Eຊາອາເມຍ\u001Eລິທົວນຽນ\u001Eລູບາ-ຄາຕັງກາ\u001Eລູບາ-ລູລົວ\u001Eລູເຊໂນ\u001Eລຸນດາ\u001Eລົວ\u001Eມີໂຊ\u001Eລູໄຍ\u001Eລັດວຽນ\u001Eມາດູລາ\u001Eມາຟາ\u001Eມາກາຮິ\u001Eໄມທີລິ\u001Eມາກາຊາຣ\u001Eມັນດິງກາ\u001Eມາໄຊ\u001Eມາບາ\u001Eມອກຊາ\u001Eມານດາຣ\u001Eເມນເດ\u001Eເມຣູ\u001Eມໍຣິສເຢນ\u001Eມາລາກາສຊີ\u001Eໄອລິດກາງ\u001Eມາຄູວາ-ມີດໂຕ\u001Eເມທາ\u001Eມາຊານເລັດ\u001Eມາວຣິ\u001Eມິກແມກ\u001Eມີແນງກາບູ\u001Eແມຊິໂດນຽນ\u001Eມາເລອາລຳ\u001Eມອງໂກເລຍ\u001Eແມນຈູ\u001Eມານີພູຣິ\u001Eອິນນຸໄອມັນ\u001Eໂມຫາ\u001Eມອສຊີ\u001Eມາຣາທີ\u001Eມາເລ\u001Eມອລທີສ\u001Eມັນດັງ\u001Eຫລາຍພາສາ\u001Eມັສໂກກີ\u001Eມີລັນດາ\u001Eມາວາຣິ\u001Eມຽນມາ\u001Eມໍຢິນ\u001Eເອີຍາ\u001Eມາແຊນເດີລັງ\u001Eນາຢູລູ\u001Eນາໂປລີ\u001Eນາມາ\u001Eນໍເວຈຽນ ບັອກມອລ\u001Eເອັນເດເບເລເໜືອ\u001Eເຢຍລະມັນ ຕອນໃຕ້\u001Eຊາຊອນ ຕອນໄຕ\u001Eເນປາລີ\u001Eນີວາຣິ\u001Eເອັນດອງກາ\u001Eນີ່ອັດ\u001Eນີ່ອູ\u001Eດັຊ\u001Eຟລີມິຊ\u001Eກວາຊີໂອ\u001Eນໍເວຈຽນ ນີນອກ\u001Eຈີ່ມບູນ\u001Eນໍເວຈຽນ\u001Eນໍໄກ\u001Eນໍໂບຮານ\u001Eເອັນໂກ\u001Eນີບີລີໃຕ້\u001Eໂຊໂທເໜືອ\u001Eເນີ\u001Eນາວາໂຈ\u001Eເນວາດັ້ງເດີມ\u001Eນານຈາ\u001Eນາມວີຊິ\u001Eນານຄອນ\u001Eໂນໂຣ\u001Eນິມາ\u001Eອັອກຊີຕານ\u001Eໂອຈິບວາ\u001Eໂອຈິບວາຕາເວັນຕົກສ່ຽງເໜືອ\u001Eໂອຈິບວາກາງ\u001Eໂອຈິຄຣີ\u001Eໂອຈິບວາຕາເວັນຕົກ\u001Eໂອກະນາກັນ\u001Eໂອໂຣໂມ\u001Eໂອເດຍ\u001Eອອດເຊຕິກ\u001Eໂອແຊກ\u001Eຕູກີອອດໂຕມັນ\u001Eປັນຈາບີ\u001Eປານກາຊີນານ\u001Eພາລາວີ\u001Eປາມປານກາ\u001Eປາມເປຍເມັນໂທ\u001Eປາລົວອານ\u001Eໄນຈີຣຽນພິດກິນ\u001Eເປີເຊຍໂບຮານ\u001Eຟີນີເຊຍ\u001Eປາລີ\u001Eປິຈິນ\u001Eໂປລິຊ\u001Eພອນເພ\u001Eມາລິຊີດ ພາສຊາມາໂຄດດີ\u001Eປຣັສຊຽນ\u001Eໂປວອງຊານໂບຮານ\u001Eປາສໂຕ\u001Eປອກຕຸຍກິສ\u001Eປອກຕຸຍກິສ ຢຸໂຣບ\u001Eຄີຊົວ\u001EKʼicheʼ\u001Eຣາຈັສທານິ\u001Eຣາປານຸຍ\u001Eຣາໂຣທອນການ\u001Eໂຣຮິນຢາ\u001Eໂຣແມນຊ໌\u001Eຣຸນດິ\u001Eໂຣແມນຽນ\u001Eໂມດາວຽນ\u001Eຣົມໂບ\u001Eໂຣເມນີ\u001Eລັດເຊຍ\u001Eອາໂຣມານຽນ\u001Eຄິນຢາວານດາ\u001Eອາຣວາ\u001Eສັນສະກຣິດ\u001Eຊັນດາວ\u001Eຊາກາ\u001Eສາມາຣິແຕນ-\u001Eຊຳບູຣູ\u001Eຊາຊັກ\u001Eຊານທາລິ\u001Eກຳເບ\u001Eຊານກູ\u001Eສາດີນຽນ\u001Eຊີຊິລີນ\u001Eສກອດ\u001Eສິນທິ\u001Eພາກໄຕ້ ຂອງ ກູດິດ\u001Eຊາມິເໜືອ\u001Eຊີນີກາ\u001Eຊີນາ\u001Eເຊນຄັບ\u001Eໂຄຍຣາໂບໂຣ ເຊນ